// Die Monatsfrist aus Art. 12 Abs. 3 DSGVO ist kalendarisch, nicht 30 Tage.
// Deshalb wird ueber setMonth gerechnet - der 31.01. plus ein Monat ist der
// 28./29.02., nicht der 02.03. Wer hier mit 30 Tagen rechnet, liegt in vier
// Monaten des Jahres daneben.
function plusEinMonat(d) {
  const ziel = new Date(d.getTime());
  const tag = ziel.getDate();
  ziel.setMonth(ziel.getMonth() + 1);
  if (ziel.getDate() < tag) ziel.setDate(0); // Ueberlauf auf Monatsende zurueckziehen
  return ziel;
}
const de = (d) => d.toLocaleDateString('de-DE');
const iso = (d) => d.toISOString().slice(0, 10);

const raus = [];
for (const eintrag of $input.all()) {
  const f = eintrag.json || {};
  const eingangRoh = String(f['Eingangsdatum des Ersuchens'] || '').trim();
  const eingang = eingangRoh ? new Date(eingangRoh) : new Date();
  const gueltig = !isNaN(eingang.getTime());
  const start = gueltig ? eingang : new Date();

  const frist = plusEinMonat(start);
  const erinnerung = new Date(start.getTime() + 20 * 24 * 60 * 60 * 1000);
  const verlaengerung = plusEinMonat(plusEinMonat(frist));

  const hinweise = [];
  if (!gueltig) hinweise.push('Eingangsdatum unlesbar - heutiges Datum angesetzt, bitte pruefen');
  if (gueltig && start.getTime() > Date.now() + 86400000) hinweise.push('Eingangsdatum liegt in der Zukunft - Tippfehler pruefen');
  // Ein spaet erfasstes Ersuchen ist der haeufigste Grund fuer Fristversaeumnis.
  const tageOffen = Math.floor((Date.now() - start.getTime()) / 86400000);
  if (tageOffen > 20) hinweise.push('Ersuchen liegt bereits ' + tageOffen + ' Tage zurueck - Frist laeuft bald ab, sofort bearbeiten');
  if (String(f['Bekannte Kundenbeziehung'] || '').startsWith('Nein')) hinweise.push('Keine bekannte Kundenbeziehung - auch eine Negativauskunft ist eine Auskunft und fristgebunden');
  if (String(f['Kopie der Daten verlangt (Art. 15 Abs. 3)?'] || '') === 'Nicht eindeutig') hinweise.push('Unklar, ob eine Kopie nach Art. 15 Abs. 3 verlangt wird - beim Antragsteller nachfragen');

  const laufnummer = String(Date.now()).slice(-6);
  raus.push({
    json: {
      vorgang_id: 'AUS-' + start.getFullYear() + '-' + laufnummer,
      eingang_de: de(start),
      eingang_iso: iso(start),
      frist_de: de(frist),
      frist_iso: iso(frist),
      erinnerung_de: de(erinnerung),
      erinnerung_iso: iso(erinnerung),
      verlaengerung_moeglich_bis_de: de(verlaengerung),
      name: String(f['Name der betroffenen Person'] || '').trim(),
      email: String(f['E-Mail der betroffenen Person'] || '').trim(),
      anschrift: String(f['Postanschrift'] || '').trim(),
      kanal: String(f['Eingangskanal'] || ''),
      umfang: String(f['Umfang des Ersuchens'] || '').trim(),
      kopie_verlangt: String(f['Kopie der Daten verlangt (Art. 15 Abs. 3)?'] || ''),
      kundenbeziehung: String(f['Bekannte Kundenbeziehung'] || ''),
      status: 'Eingegangen - Identitaetspruefung offen',
      identitaet_geprueft: 'nein',
      hinweise: hinweise.join(' | ')
    }
  });
}
return raus;

