// Art. 15 Abs. 1 DSGVO listet acht Pflichtangaben. Eine Auskunft, die nur
// die Daten selbst enthaelt, ist unvollstaendig - deshalb wird hier ein
// Geruest entlang lit. a bis h erzeugt, das die verantwortliche Person
// befuellt bzw. bestaetigt. Die Systemliste ist der eigentliche Knackpunkt:
// vergessene Quellen sind der haeufigste Grund fuer unvollstaendige Auskuenfte.
const vorgang = $('Fristen berechnen').item.json;
const antwort = $input.first().json || {};

// An die eigene Systemlandschaft anpassen.
const QUELLEN = ['CRM', 'ERP / Warenwirtschaft', 'Newsletter-Tool', 'Ticketsystem / Support', 'Buchhaltung', 'Bewerbermanagement', 'Telefonanlage / Gespraechsnotizen', 'Backups'];

const treffer = Array.isArray(antwort.treffer) ? antwort.treffer : (Array.isArray(antwort.results) ? antwort.results : []);
const abgefragt = treffer.map(t => String(t.quelle || t.source || '')).filter(Boolean);
const offen = QUELLEN.filter(q => !abgefragt.some(a => a.toLowerCase().includes(q.toLowerCase().split(' ')[0])));
const apiErreichbar = treffer.length > 0 || Array.isArray(antwort.treffer);

const z = [];
z.push('# Entwurf Auskunft nach Art. 15 DSGVO - ' + vorgang.vorgang_id);
z.push('');
z.push('Antragsteller: ' + vorgang.name + ' (' + vorgang.email + ')');
z.push('Eingang: ' + vorgang.eingang_de + ' | Frist: ' + vorgang.frist_de);
z.push('Identitaet: durch die verantwortliche Person bestaetigt am ' + new Date().toLocaleDateString('de-DE'));
z.push('');
z.push('## Pflichtangaben nach Art. 15 Abs. 1');
z.push('a) Verarbeitungszwecke: [ausfuellen]');
z.push('b) Kategorien personenbezogener Daten: [ausfuellen]');
z.push('c) Empfaenger oder Kategorien von Empfaengern, auch in Drittlaendern: [ausfuellen]');
z.push('d) Geplante Speicherdauer oder Kriterien zu ihrer Festlegung: [ausfuellen]');
z.push('e) Hinweis auf Berichtigung, Loeschung, Einschraenkung und Widerspruch: Standardtext einfuegen');
z.push('f) Hinweis auf das Beschwerderecht bei einer Aufsichtsbehoerde: Standardtext einfuegen');
z.push('g) Herkunft der Daten, wenn nicht bei der Person erhoben: [ausfuellen]');
z.push('h) Automatisierte Entscheidungsfindung einschliesslich Profiling: [ausfuellen, sonst ausdruecklich verneinen]');
z.push('');
z.push('## Rechercheergebnis je Datenquelle');
if (treffer.length === 0) {
  z.push('- Keine maschinellen Ergebnisse vorhanden. Alle Quellen manuell abfragen und hier dokumentieren.');
} else {
  for (const t of treffer) {
    z.push('- ' + (t.quelle || t.source || 'unbenannte Quelle') + ': ' + (t.anzahl ?? t.count ?? 'unbekannt') + ' Datensaetze' + (t.hinweis ? ' (' + t.hinweis + ')' : ''));
  }
}
z.push('');
z.push('## Noch manuell zu pruefende Quellen');
if (offen.length === 0) z.push('- keine');
for (const q of offen) z.push('- ' + q + ' [Ergebnis eintragen, auch Fehlanzeige dokumentieren]');
z.push('');
z.push('## Vor dem Versand pruefen');
z.push('- Rechte und Freiheiten anderer Personen (Art. 15 Abs. 4): Daten Dritter schwaerzen oder herausnehmen');
z.push('- Beschraenkungen nach Par. 34 BDSG pruefen');
z.push('- Kopie nach Art. 15 Abs. 3 verlangt: ' + vorgang.kopie_verlangt);
z.push('- Sicherer Versandweg: verschluesselt oder per Einschreiben, nicht unverschluesselt per Mail');
z.push('- Bei Ablehnung oder Teilauskunft: Begruendung und Hinweis auf Beschwerderecht');

const warnungen = [];
if (!apiErreichbar) warnungen.push('Datenquellen-API nicht erreichbar oder nicht konfiguriert - Recherche vollstaendig manuell durchfuehren');
if (offen.length > 0) warnungen.push(offen.length + ' Quelle(n) ohne maschinelles Ergebnis');

return [{
  json: {
    ...vorgang,
    identitaet_geprueft: 'ja',
    status: 'Entwurf erstellt - inhaltliche Pruefung und Versand offen',
    quellen_offen: offen.join(', '),
    warnungen: warnungen.join(' | '),
    zusammenstellung: z.join('\n')
  }
}];

